import React, { useState, useEffect } from "react";
import { X } from "lucide-react";

function JobForm({ job, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    title: "",
    role: "",
    skillset: "",
    ctc: "",
    location: "",
    experience: "",
    jobType: "Full-time",
    department: "",
    description: "",
    responsibilities: "",
    qualifications: "",
    benefits: "",
    deadline: "",
  });

  const [loading, setLoading] = useState(false);

  const fieldLabels = {
    title: "Job Title",
    role: "Role/Position",
    skillset: "Skillset",
    ctc: "CTC",
    location: "Location",
    experience: "Experience",
    jobType: "Job Type",
    department: "Department",
    description: "Description",
    responsibilities: "Responsibilities",
    qualifications: "Qualifications",
    benefits: "Benefits & Perks",
    deadline: "Deadline",
  };

  const mandatoryFields = ["title", "role", "skillset", "ctc", "location", "experience", "description"];

  const placeholders = {
    title: "e.g. Frontend Developer",
    role: "e.g. UI Engineer",
    skillset: "e.g. React, JS, CSS",
    ctc: "e.g. 3 LPA, 5 LPA",
    location: "e.g. Bengaluru, Remote",
    experience: "e.g. 2 years, 5 years",
    department: "e.g. Engineering, HR",
    description: "Job description here...",
    responsibilities: "Key responsibilities...",
    qualifications: "Required qualifications...",
    benefits: "e.g. Health insurance, Paid leaves",
    deadline: "",
  };

  useEffect(() => {
    if (job) {
      setFormData({
        title: job.title || "",
        role: job.role || "",
        skillset: job.skillset || "",
        ctc: job.ctc || "",
        location: job.location || "",
        experience: job.experience || "",
        jobType: job.jobType || "Full-time",
        department: job.department || "",
        description: job.description || "",
        responsibilities: job.responsibilities || "",
        qualifications: job.qualifications || "",
        benefits: job.benefits || "",
        deadline: job.deadline || "",
      });
    } else {
      const today = new Date().toISOString().split("T")[0];
      setFormData({
        title: "",
        role: "",
        skillset: "",
        ctc: "",
        location: "",
        experience: "",
        jobType: "Full-time",
        department: "",
        description: "",
        responsibilities: "",
        qualifications: "",
        benefits: "",
        deadline: today,
      });
    }
  }, [job]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async () => {
    for (let field of mandatoryFields) {
      if (!formData[field] || formData[field].trim() === "") {
        alert(`${fieldLabels[field]} is mandatory!`);
        return;
      }
    }

    const filledData = {};
    Object.keys(formData).forEach((key) => {
      if (formData[key]) {
        filledData[key] = formData[key];
      }
    });

    setLoading(true);
    try {
      await onSubmit(filledData);
      resetForm();
    } catch (err) {
      console.error("Error in onSubmit:", err);
      alert("Failed to save job. Check console for details.");
    }
    setLoading(false);
  };

  const resetForm = () => {
    const today = new Date().toISOString().split("T")[0];
    setFormData({
      title: "",
      role: "",
      skillset: "",
      ctc: "",
      location: "",
      experience: "",
      jobType: "Full-time",
      department: "",
      description: "",
      responsibilities: "",
      qualifications: "",
      benefits: "",
      deadline: today,
    });
    onClose();
  };

  return (
    <div style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, backgroundColor: "rgba(0,0,0,0.6)", display: "flex", alignItems: "flex-start", justifyContent: "center", paddingTop: "60px", zIndex: 1000 }}>
      <div style={{ background: "#fff", width: "90%", maxWidth: "800px", borderRadius: "12px", boxShadow: "0 8px 30px rgba(0,0,0,0.2)", overflow: "hidden" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "18px 24px", borderBottom: "1px solid #e2e8f0" }}>
          <h2 style={{ fontSize: "20px", fontWeight: "600", color: "#1e293b", margin: 0 }}>{job ? "Edit Job" : "Add New Job"}</h2>
          <button onClick={resetForm} style={{ background: "none", border: "none", cursor: "pointer", padding: "4px", color: "#64748b" }}>
            <X size={22} />
          </button>
        </div>

        <div style={{ padding: "24px", maxHeight: "70vh", overflowY: "auto" }}>
          {Object.keys(formData).map((field) => (
            <div key={field} style={{ marginBottom: "18px" }}>
              <label style={{ fontSize: "14px", fontWeight: 500, color: "#374151", marginBottom: "6px", display: "block" }}>
                {fieldLabels[field]}
                {mandatoryFields.includes(field) && <span style={{ color: "red", marginLeft: "3px" }}>*</span>}
              </label>

              {field === "jobType" ? (
                <select name={field} value={formData[field]} onChange={handleChange} style={{ width: "100%", padding: "10px 12px", border: "1px solid #cbd5e1", borderRadius: "8px", fontSize: "14px", color: "#1e293b", outline: "none", boxSizing: "border-box" }}>
                  <option>Full-time</option>
                  <option>Part-time</option>
                  <option>Contract</option>
                  <option>Internship</option>
                </select>
              ) : ["description", "responsibilities", "qualifications", "benefits"].includes(field) ? (
                <textarea name={field} rows={field === "description" ? 4 : 3} value={formData[field]} onChange={handleChange} placeholder={placeholders[field]} style={{ width: "100%", padding: "10px 12px", border: "1px solid #cbd5e1", borderRadius: "8px", fontSize: "14px", color: "#1e293b", outline: "none", boxSizing: "border-box" }} />
              ) : (
                <input type={field === "deadline" ? "date" : "text"} name={field} value={formData[field]} onChange={handleChange} placeholder={placeholders[field]} style={{ width: "100%", padding: "10px 12px", border: "1px solid #cbd5e1", borderRadius: "8px", fontSize: "14px", color: "#1e293b", outline: "none", boxSizing: "border-box" }} />
              )}
            </div>
          ))}
        </div>

        <div style={{ display: "flex", justifyContent: "flex-end", gap: "12px", padding: "16px 24px", borderTop: "1px solid #e2e8f0", backgroundColor: "#f9fafb" }}>
          <button onClick={handleSubmit} style={{ padding: "10px 16px", border: "none", borderRadius: "8px", fontSize: "14px", cursor: "pointer", fontWeight: "500", background: "#2563eb", color: "#fff", opacity: loading ? 0.6 : 1 }} disabled={loading}>
            {loading ? "Saving..." : job ? "Update Job" : "Add Job"}
          </button>
          <button onClick={resetForm} style={{ padding: "10px 16px", border: "none", borderRadius: "8px", fontSize: "14px", cursor: "pointer", fontWeight: "500", background: "#e2e8f0", color: "#1e293b" }}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

export default JobForm;
